# -*- coding: utf-8 -*-
"""R90 盲测席 B07+B08（40 例全六爻）预测生成脚本。
只读 batches.json 取本批 id；产出逐件写入 runs/round90/predictions/<case_id>.json。
分段落盘：B07 写后断言，B08 写后断言，末尾回读自验。
"""
import json, os

BASE = "/home/hatch/workspace/divination/benchmark/phase3/runs/round90"
OUT = os.path.join(BASE, "predictions")
os.makedirs(OUT, exist_ok=True)

batches = json.load(open(os.path.join(BASE, "batches.json"), encoding="utf-8"))
B07 = batches["B07"]
B08 = batches["B08"]
assert len(B07) == 20 and len(B08) == 20, (len(B07), len(B08))

P = {}  # case_id -> record

def add(cid, prediction_text, basis, confidence, cm, ru, di, reason):
    assert cid not in P
    P[cid] = {
        "case_id": cid,
        "prediction_text": prediction_text,
        "basis": basis,
        "confidence": confidence,
        "trigger": {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason},
    }

