# ---- B08 落盘 + 断言 ----
assert set(P.keys()) == set(B07) | set(B08), (sorted(set(B07 + B08) - set(P)), sorted(set(P) - set(B07 + B08)))
for cid in B08:
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(P[cid], f, ensure_ascii=False, indent=2)
print("B08 written:", len(B08))

# ---- 回读自验：逐件按本批 id 清单精确打开 ----
need = {"case_id", "prediction_text", "basis", "confidence", "trigger"}
cnt = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
n = 0
for cid in B07 + B08:
    d = json.load(open(os.path.join(OUT, cid + ".json"), encoding="utf-8"))
    assert need <= set(d.keys()), cid
    assert d["case_id"] == cid
    assert isinstance(d["confidence"], (int, float)) and 0 <= d["confidence"] <= 1
    t = d["trigger"]
    assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}, cid
    for k in cnt:
        assert isinstance(t[k], bool)
        if t[k]:
            cnt[k] += 1
    assert isinstance(t["reason"], str)
    if any(t[k] for k in cnt):
        assert t["reason"], cid
    n += 1
print("verified files:", n)
print("trigger counts:", cnt)
sizes = {cid: os.path.getsize(os.path.join(OUT, cid + ".json")) for cid in B07 + B08}
print("total bytes:", sum(sizes.values()))
print("min/max file bytes:", min(sizes.values()), max(sizes.values()))
